   442  static ssize_t expect_continuation_of_headers(h2o_http2_conn_t *conn, const uint8_t *src, size_t len, const char **err_desc)
   443  {
   444      h2o_http2_frame_t frame;
   445      ssize_t ret;
   446      h2o_http2_stream_t *stream;
   447      int hret;
   448
   449      if ((ret = h2o_http2_decode_frame(&frame, src, len, &H2O_HTTP2_SETTINGS_HOST, err_desc)) < 0)
   450          return ret;
   451      if (frame.type != H2O_HTTP2_FRAME_TYPE_CONTINUATION) {
   452          *err_desc = "expected CONTINUATION frame";
   453          return H2O_HTTP2_ERROR_PROTOCOL;
   454      }
   455
   456      if (conn->state >= H2O_HTTP2_CONN_STATE_HALF_CLOSED)
   457          return 0;
   458
   459      if ((stream = h2o_http2_conn_get_stream(conn, frame.stream_id)) == NULL ||
   460          !(stream->state == H2O_HTTP2_STREAM_STATE_RECV_HEADERS || stream->state == H2O_HTTP2_STREAM_STATE_RECV_BODY)) {
   461          *err_desc = "unexpected stream id in CONTINUATION frame";
   462          return H2O_HTTP2_ERROR_PROTOCOL;
   463      }
   464
   465      if (conn->_headers_unparsed->size + frame.length <= H2O_MAX_REQLEN) {
   466          h2o_buffer_reserve(&conn->_headers_unparsed, frame.length);
   467          memcpy(conn->_headers_unparsed->bytes + conn->_headers_unparsed->size, frame.payload, frame.length);
   468          conn->_headers_unparsed->size += frame.length;
   469
   470          if ((frame.flags & H2O_HTTP2_FRAME_FLAG_END_HEADERS) != 0) {
   471              conn->_read_expect = expect_default;
   472              if (stream->state == H2O_HTTP2_STREAM_STATE_RECV_HEADERS) {
   473                  hret = handle_incoming_request(conn, stream, (const uint8_t *)conn->_headers_unparsed->bytes,
   474                                                 conn->_headers_unparsed->size, err_desc);
   475              } else {
   476                  hret = handle_trailing_headers(conn, stream, (const uint8_t *)conn->_headers_unparsed->bytes,
   477                                                 conn->_headers_unparsed->size, err_desc);
   478              }
   479              if (hret != 0)
   480                  ret = hret;
   481              h2o_buffer_dispose(&conn->_headers_unparsed);
   482              conn->_headers_unparsed = NULL;
   483          }
   484      } else {
   485          /* request is too large (TODO log) */
   486          stream_send_error(conn, stream->stream_id, H2O_HTTP2_ERROR_REFUSED_STREAM);
   487          h2o_http2_stream_reset(conn, stream);
   488      }
   489
   490      return ret;
   491  }
